"""Assemble the follow-up proof in the platform's required single-file format."""
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def render():
    chunks = ['import OMAStatements.S_oeis_a283508\nimport Mathlib\n\n'
              '/-! Proof of OEIS A283508. Credit: @ddanila.\n'
              'Generated by scripts/package_proof.py from the checked local proofs.\n'
              'Submit only after the statement is merged; the imported target fixes the claim. -/\n']
    for name in ['Basic', 'Proof', 'GeneratingFunction', 'Rule187']:
        source = (ROOT/f'A283508/{name}.lean').read_text()
        chunks.append('\n'.join(line for line in source.splitlines() if not line.startswith('import ')))
    certificate = (ROOT/'scripts/Certificate.lean').read_text()
    certificate = certificate[:certificate.index('-- Definitional equality')]
    chunks.append(certificate+'end OMA.S_oeis_a283508\n')
    chunks.append('theorem OMA.solution : type_of% @OMA.S_oeis_a283508.main :=\n'
                  '  OMA.S_oeis_a283508.certified\n')
    return '\n\n'.join(chunks)


if __name__ == '__main__':
    (ROOT/'proofs').mkdir(exist_ok=True)
    (ROOT/'proofs/oeis-a283508.lean').write_text(render())
